package zw.shallom.servlet;
import javax.servlet.annotation.*;import javax.servlet.http.*;import javax.servlet.*;import java.io.IOException;import java.util.*;import zw.shallom.service.SchoolService;import zw.shallom.model.*;
@WebServlet("/app/*") public class AppServlet extends HttpServlet {
 private SchoolService service(HttpServletRequest q){return (SchoolService)getServletContext().getAttribute("school");}private User user(HttpServletRequest q){return (User)q.getSession().getAttribute("user");}
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String key=q.getPathInfo();if(key==null||key.equals("/"))key="/dashboard";SchoolService s=service(q);User u=user(q);String view=key.substring(1);q.setAttribute("view",view);q.setAttribute("school",s);q.setAttribute("user",u);q.setAttribute("payments",u.getRole()==Role.STUDENT?s.history(u.getUsername()):s.payments());q.setAttribute("results",s.results());q.setAttribute("issues",s.issues());q.setAttribute("subjects",SchoolService.SUBJECTS);q.setAttribute("sports",SchoolService.SPORTS);q.setAttribute("classes",SchoolService.CLASSES);q.getRequestDispatcher("/WEB-INF/views/main.jsp").forward(q,p);}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String key=q.getPathInfo();SchoolService s=service(q);User u=user(q);try{if("/fees".equals(key)){String id=q.getParameter("studentId");if(id==null||!id.equals(u.getUsername()))throw new IllegalArgumentException("Student ID must match your signed-in account.");Payment payment=s.pay(u,id,Double.parseDouble(q.getParameter("amount")),q.getParameter("method"));q.setAttribute("receipt",payment);doGet(q,p);return;}if("/marks".equals(key)){if(u.getRole()!=Role.TEACHER)throw new IllegalArgumentException("Teacher access required.");int mark=Integer.parseInt(q.getParameter("mark"));if(mark<0||mark>100)throw new IllegalArgumentException("Marks must be between 0 and 100.");s.addResult(q.getParameter("student"),q.getParameter("subject"),mark,u.getUsername());}else if("/issues".equals(key)){if(u.getRole()!=Role.ANCILLARY)throw new IllegalArgumentException("Ancillary staff access required.");String d=q.getParameter("description");if(d==null||d.trim().length()<4)throw new IllegalArgumentException("Describe the issue (at least four characters).");s.addIssue(u.getName(),d.trim());}q.getSession().setAttribute("notice","Your submission was saved.");p.sendRedirect(q.getContextPath()+"/app/"+(key.substring(1)));}catch(Exception e){q.setAttribute("error",e.getMessage());doGet(q,p);}}
}
